// ---- Constants

#define VECTORS 0x27u   // the vector table's entries, 0 (the reset) to 38 (TIM2)
#define CSR_INTSYSCR 0x804u   // INTSYSCR: HWSTKEN (bit 0, HPE) and INESTEN (bit 1, nesting), both 0 after reset
#define INTSYSCR_HWSTKEN 0x1u   // INTSYSCR: the hardware prologue/epilogue (HPE)
#define INTSYSCR_INESTEN 0x2u   // INTSYSCR: interrupt nesting
#define MTVEC_VECTORED 0x1u   // mtvec MODE0: the entry is the base + 4 * the number (0: one entry for all)
#define MTVEC_ADDRESSES 0x2u   // mtvec MODE1: the table holds the handlers' addresses (0: instructions)
#define MTVEC_ALIGN 0x400u   // the vector table's base must be 1 KB aligned (QKV2 2.2, mtvec)
#define RCC_SW_HSI 0x0u   // RCC_CFGR0.SW and SWS: the HSI (24 MHz) is the system clock
#define RCC_SW_PLL 0x2u   // RCC_CFGR0.SW and SWS: the PLL (HSI or HSE * 2) is the system clock
#define FLASH_LATENCY_24MHZ 0x0u   // FLASH_ACTLR.LATENCY: 0 wait states, for SYSCLK up to 24 MHz
#define FLASH_LATENCY_48MHZ 0x1u   // FLASH_ACTLR.LATENCY: 1 wait state, for SYSCLK from 24 to 48 MHz
#define HSI_HZ 0x16e3600ul   // the internal RC oscillator, the system clock after reset (RM 3.3.2)
#define PLL_HZ 0x2dc6c00ul   // the PLL from the HSI: 2 * 24 MHz, the most the chip runs at (RM 3.3.1)

